import{p as e,b as t,C as o}from"./vue-vendor-de6b2611.js";const c={class:"markdown-body"},a=o("<h1>BIOS 常见设置</h1><h2>基础操作</h2><table><thead><tr><th>项目</th><th>R2</th><th>R2 Max</th></tr></thead><tbody><tr><td>进入 BIOS 快捷键</td><td><code>F2</code></td><td><code>Esc</code> 或 <code>F2</code></td></tr><tr><td>启动顺序快捷键</td><td><code>F12</code></td><td><code>F11</code></td></tr><tr><td>恢复默认出厂设置</td><td><code>Save &amp; Exit</code> → <code>Restore Defaults</code></td><td><code>Save &amp; Exit</code> → <code>Restore Defaults</code></td></tr></tbody></table><h2>电源与唤醒设置</h2><table><thead><tr><th>设置项</th><th>R2</th><th>R2 Max</th></tr></thead><tbody><tr><td>来电启动</td><td><code>Chipset</code> → <code>PCH-IO Configuration</code> → <code>State After G3</code>；来电自启选择 <code>S0 State</code>，手动开关机选择 <code>S5 State</code></td><td><code>Advanced</code> → <code>IT8613 Super IO Configuration</code> → <code>Restore AC Power Loss</code></td></tr><tr><td>USB 口带电</td><td><code>Chipset</code> → <code>USB 5V Configuration</code> → <code>USB 5V ALWAY</code></td><td><code>Advanced</code> → <code>IT8613 Super IO Configuration</code> → <code>USB Power CTL</code></td></tr><tr><td>网口带电与 WOL</td><td><code>Chipset</code> → <code>PCIE LAN Configuration</code> → <code>Wake on LAN Enable</code></td><td><code>Advanced</code> → <code>ACPI Settings</code> → <code>Wake by onboard LAN</code></td></tr></tbody></table><h2>风扇设置</h2><table><thead><tr><th>设置项</th><th>R2</th><th>R2 Max</th></tr></thead><tbody><tr><td>PWM 风扇</td><td><code>Advanced</code> → <code>Hardware Monitor</code> → <code>Smart Fan Function</code> → <code>CPU Fan Configuration</code>；可选 <code>Normal Mode</code>、<code>Manual Mode</code>、<code>Full on Mode</code></td><td><code>Advanced</code> → <code>Hardware Monitor</code>；支持 <code>PWM Mode</code>、<code>Full on Speed</code>、<code>Fan Off Mode</code></td></tr></tbody></table>",7),r=[a],S={__name:"bios",setup(n,{expose:d}){return d({frontmatter:{}}),(s,i)=>(e(),t("div",c,r))}};export{S as default};
